import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"復","description":"高岛易断 - 復","frontmatter":{"title":"復","description":"高岛易断 - 復"},"headers":[],"relativePath":"zh/classics/takashima/024.md","filePath":"zh/classics/takashima/024.md"}'),i={name:"zh/classics/takashima/024.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="復" tabindex="-1">復 <a class="header-anchor" href="#復" aria-label="Permalink to “復”">​</a></h1><h2 id="復-1" tabindex="-1">復 <a class="header-anchor" href="#復-1" aria-label="Permalink to “復”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>复：亨。出入无疾，朋来无咎，反复其道，七日来复。利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《复》之内卦一画，自《乾》之下画来，一阳即《乾》，“亨”即从乾元来，故曰“亨”。外《坤》内《震》，出《震》入《坤》，《坤》为顺，《震》为动，以顺而动，阴不能伤，故“无疾”。同类为“朋”，《震》一阳，《兑》二阳，《兑》为朋。一阳先至，朋类皆来，阴不能阻，故“无咎”。《剥》之卦，一阳在上而几尽，《复》则一阳反生于下，故曰“反复其道”，“道”，路也。“七日来复”，姤五月卦，阴气始生，《复》十一月卦，阳气始生，阴阳反复，凡历七月，七阳数，故言“七日”。此为“君子道长”之机，故曰“利有攸往”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>雷在地中，复，先王以至日闭关，商旅不行，后不省方。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>此卦为十一月卦，故《象》取“至日”，是雷伏藏地中也。先王观此象，以“至日闭关”而不启，止商旅而不行，后于是日，亦“不省方”，盖为养其阳气之方来，而不敢或泄，务为安静，所以葆其贞也。月令仲冬，审门闾，谨房室，必重闭，推之即可知“闭关”之诸象焉。“闭关”取《坤》为阖户，“商旅”取《坤》为众民，“行”取《震》为大途，“方”取《坤》为国土。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：好运初来，尚未发动，静以待之，自然获吉。</p><p>○　问商业：货物完备，时价亦动，宜暂停售，必得利也。</p><p>○　问家宅：此宅现时闭歇，须待春时，方可迁居。吉。</p><p>○　问战征：防敌军埋伏地雷，须暂停战，以养兵力。吉。</p><p>○　问疾病：是痰火之症，饮食不进，交冬令宜防。</p><p>○　问讼事：一时不能审结。</p><p>○　问六甲：生男，交春分产。</p><p>○　问婚嫁：现因媒人尚未往说，春初可成。吉。</p><p>○　问行人；冬季不归，开春归来。</p><p>○　问失物：一时难觅，日后可得。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>此卦初九一阳，自《乾》阳来，入《坤》群阴中，忽复本位，名之曰《复》。卦之《复》就造化言，爻之《复》就人心言是也。此爻《复》之初，为《复》道之始。七日即复，故曰“不远”，是以不至悔而得“元吉”也。“元吉”者，即复《乾》之吉也。“祗”者至也，人虽圣贤，不能无过，惟贵速改，过而不改，则有悔而凶可知也。《象传》曰“以修身也”，修者所以补其缺，正其误也。占者知此，则人欲日消，天理日明，可以为圣，可以为贤。“修身”二字，包括深远，不可不知也，何则？六二之《传》日“仁”而称美之，六四之《传》曰“道”而赞叹之。“修身”二字，兼仁与道，其所关至大。心内而身外，以存养言，则在心；以修为言，则在身：身心一也。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：好运即来，渐渐发动，一往顺利，大吉。</p><p>○　问商业：前所耗失，即可复得，可免悔恨，大吉。</p><p>○　问家宅：旧业复兴，即在目前，大吉。</p><p>○　问战征：即日可转败为成，大吉。</p><p>○　问讼事：始审不直，再控必胜，大吉。</p><p>○　问婚嫁：主散而复成，大吉。</p><p>○　问行人：不日即归，吉。</p><p>○　问疾病：静养即可复，元吉。</p><p>○　问六甲：即日生男。</p><p>○　问失物：即日可得。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>余欲购驱车之马，适遇儿玉少介君曰：余去岁求良马于南部，后无音信，遂别购一马，顷日南部马至，厩隘不容。谓余买之，余乃占其良否，筮得《复》之《坤》。</p><p>断曰：此马不适长途，朝出夕归，得其宜耳。爻谓“不远复，无祗悔，元吉”，可以见矣。初爻变则为《坤》，《坤》曰“利牝马之贞”，知此马必牝，无暴逸之虞者也。后购得其马，果如此占，性柔顺，最适驾车。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>此爻以阴居阴，得其中正，与初九切比，志从于阳。嘉初之能复于道，甘心下己，以友其仁，切磋琢磨，恶念潜消，善心日生，故曰“休复，吉”。初爻得《乾》阳之正，开《复》道之首，故曰“元吉”；六二取人为善，自能从容改图，其功次于初矣，故曰“吉”。《象传》曰“以下仁也”，初复于仁，二比而下之，是以吉也。《易》三百八十四爻，未尝言仁，此爻言之。所谓“复其见天地之心”者，天地之心，即仁也；所谓仁，元善之旨也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下气运亦好，事事能择善而从，故事事得吉。</p><p>○　问商业：能与人共利，其业必兴，吉。</p><p>○　问家宅：家庭多休祥之征，自能兴复旧业。吉。</p><p>○　问战征：一时暂休攻克，姑示其弱，以养锐气。吉。</p><p>○　问疾病：宜初治之医，复诊视之。吉。</p><p>○　问行人：必从长辈而归。</p><p>○　问六甲：生女。</p><p>○　问失物：就低下处寻之。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十四年春，某裁判所长及检事长，访余山庄，请占某贵显辞表后之举止，筮得《复》之《临》。</p><p>断曰：雷者，春夏升出于地上，秋冬潜与地中。此卦雷复地中，而将再出者也，故某贵显今日虽优游闲居，可知其复职不远也。两君怪余断之轻易，曰：《易》如此容易，天下之事，悉可问之于《易》也。余曰：固然。《易》之包蕴甚广，天下之事物，无一不具，而其变化神妙，不可测度，是以无事无物而不可占也。占之则过去、现在、未来皆得明示，其应如响。即贵下于两造之事，多匿奸藏诈，掩非为是，诬真为假，不易剖决者，占之而奸计显露，所谓问诸人，不如问诸神也。不然，贵下等只据法律，凭口辞，安能一一无枉乎？古云“卜以决疑”，此之谓也。在某贵显之辞职，世论嚣嚣，余一揲蓍，神示之以地下有雷之象，二爻之辞曰“休复”，知其一时休职，他日必复职也，明矣。《象传》曰，“休复之吉，以下仁也”，即此可知矣。二人倾服而去。后某贵显果复职，钦服余断之不妄也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三爻位不中正，志刚而质柔，质柔则见事而不明，志刚则狂躁而妄动，故屡复而屡失，是以有“厉”，亦屡失而屡复，终可“无咎”也。虽有失身亏行之惧，自无长傲遂非之过，故曰“频复，厉，无咎”。周公之系辞，隐其屡过之罪，称其“频复”之善；孔子释之曰“义无咎也”，是开人以改过迁善乏门也。意深哉！</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：一好一歹，时有得失，能据其得而不失，是在人也。</p><p>○　问商业：有亏有盈，能使盈多亏少，亏而复盈，亦可获利。</p><p>○　问家宅：有迁移不定之象。</p><p>○　问疾病：屡治屡发，虽危，可保无害。</p><p>○　问讼事：有频翻口供，转致危厉之象。</p><p>○　问行人：归志未决。</p><p>○　问六甲：生男，颇涉难产，无害。</p><p>○　问失物：失非一次，当可寻得。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>一商人来请占气运，筮得《复》之《明夷》。爻辞曰：“六三：频复，厉，无咎。”</p><p>断曰：《复》为雷藏地中，阳气来复之时，在人为迷惑情态，有悔悟复本之象。三爻位不中正，辞曰“频复，厉，无咎”，是谓屡兴屡败，劳而无功。其不至破产者，由于随时省悟，随失随改，故“无咎”也。夫运之盛衰，天数不可免，在盛运时，如放舟于上流，扬帆于顺风，不劳而取功；当其衰运，如浮舟于逆风，以溯上流，不特劳而无功，其不被损伤者殆稀。占者恐坐此弊，尤当注意气运之盛衰也。至明后年，气运乃可回复。商人闻之，感曰：实如此占，从来屡遭失败，今闻之，始悟其误。谨守常业，以待时运。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>此爻居五阴骈列之中央，独应初爻之卦主，故能杰出群阴之间，依附仁人，是心知好善，不移习俗，而能复道者也，故曰“中行独复”。所谓“择乎中庸，得一善，则拳拳服膺，而不失之”者也。然其所复犹微，故不曰吉。《象传》曰“以从道也”，谓初复于道，而四从之，故曰“从道”。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：气运柔弱，意欲振兴，惜力不能逮。</p><p>○　问商业：谋划精当，不失其正，资本未充，为可惜也。</p><p>○　问家宅：女眷多，男丁少，未免有独寐寤歌之慨。</p><p>○　问战征：防中道设伏。</p><p>○　问疾病：虚弱之症，宜从初治之医调治。</p><p>○　问行人：至中路复回，得伴再归。</p><p>○　问婚嫁：宜从前媒。</p><p>○　问失物：半途觅之。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>明治二十二年六月，友人某来曰：有人欲购余地，约以相当之价，领收约定金若干。其先亦有人欲购此地，余未定约，今复过余，所约之价高于前购，于是余将致偿金于前约之人，请其解约，但不知彼果肯允诺否？请为一筮。筮得《复》之《震》。</p><p>断曰：《复》者一阳来复之卦，有百事复旧之象。故得此卦，旅行无音信者，突然还家，贷金涩滞者，忽而归复，放荡游惰者，能复其本心，皆《复》之象也。则知足下已约之地，亦无阻障，必可复返也。后果如此占。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五有柔中之德，尊居君位，位得中，故能“复”，《坤》为厚，故曰“敦”。自知其非，不惮迁善，既能复之，又加以“敦”，是知之明，力之笃也，则一得而弗失之矣，何悔之有？故曰“敦复无悔”。《象传》曰，“中以自考也”，谓初之复，复在近，可免于悔，五之《复》，复于厚，悔之有无未知，时当返而“自考”也。盖初之“不远复”，入德之事，五之“敦复”，成德之事也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：目下气运当正，事事从厚，有前功，无后悔</p><p>○　问商业：资财充足，往复获利。</p><p>○　问家宅：祖基深厚，旧业复光，吉。</p><p>○　问战征：军力厚实，可以攻复城池也。</p><p>○　问疾病：病者精神充足，气体丰腴，无患也。</p><p>○　问六甲：生男。</p><p>○　问失物：宜自忖度。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>某局长来，请占气运，筮得《复》之《屯》。</p><p>断曰：《复》者雷在地中之象，动极复静，故谓之《复》。今占得五爻，言修身复道者，复之不已，而又复之，故曰“敦复”。其复如是，亦可谓责躬自厚，而薄责于人者矣。此人督率众人，众心感服，复何有悔？时运可知矣。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻居《复》之终，《坤》之极，《坤》为迷，故曰“迷复”。迷而不复，故必有凶。“有灾眚”，灾自外来，眚由自作，迷溺至此，无往非害。《坤》为众，《震》为行，故“用行师”。《坤》上六所云“龙战于野，其血玄黄”，即行师大败之证也。“行师”既至“大败”，国君焉得不凶？兵连祸结，至十年而未已。十年者数之终，一败而终不能振，即谓有迷而终不能复矣。盖天下之祸，无不由一念之迷溺而来，迷在于身，则一身被祸，迷在于国，则一国被祸，深著迷复之害也。《象传》曰“反君道也”，《复》之君，初九阳也，《姤》之君，初六阴也，上迷复，不奉《复》之九，而奉《姤》之六，是阴阳相反也，故曰“反君道也”。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：气运颠倒，作事乖张，谨慎免祸。</p><p>○　问商业：货物不齐，期约不准，市价不的，必致大耗；时不能《复》业，凶。</p><p>○　问家宅：防有怪崇，居者多不利。</p><p>○　问战征：辙乱旗靡，大败之象。</p><p>○　问疾病：症已危险，久病延年，犹为幸也。</p><p>○　问行人：在外多凶，十年内恐不能归也。</p><p>○　问六甲：生女。此女长成，亦大败之命。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十年六月，板垣退助君奉朝命自高知县来，朝廷赏赐爵位，以酬前功，氏固辞者再，于是世人多评论之。或曰：氏之决意辞赐，是板垣氏之所以为板垣氏，其廉退逊让，非他人所能及。氏为自由党之首领，鼓舞众人，其伸张自由之声势，一旦受爵荣，未免为党中人窃笑乎？或曰：爵位者，朝廷之荣命，氏固辞不受，未免有违敕之谴也。余与板垣君有旧，缘是欲忠告之。往访旅亭，将命者以病谢，余遂转访佐佐木高行伯，面谒曰：余每岁冬至，斋戒沐浴，敬占国事及诸当道命运。兹占板垣君，得《地雷复》上爻。</p><p>断曰：《复》者，一阳来复之卦，积阴之下伏一阳。以人事观之，全使此一点微阳渐生渐发，天下绝大事业，皆从此一阳中做出来，国家之由乱而治，人生去邪从正，悉赖焉。今占得上爻，辞曰：“迷复，凶”，是冥迷沉溺，失其本然之明者也，乃至天灾人眚之并臻，辱君丧师而莫救，危之至矣，祸莫大焉。爻辞凶恶如是，窃为板垣君虑之。昔板垣君秉政要路，大有功烈，今既辞职，其所主张专在自由党中，人众类杂，薰莸不齐，他日激而生变，亦不可测也。爻辞之凶，其或兆于此乎？顷又为板垣君辞爵再卜一卦，筮得《困》之《大过》。爻辞曰：“九二：困于酒食。朱绂方来，利用享祀。征凶，无咎。”此卦四五之阳为三上两阴所蔽，二之阳亦为初三两阴所蔽，不能通志，是以成困。“困于酒食”者，见板垣氏现时之困难也；“朱绂方来”者，谓荣命之下来也；“利用享祀”者，谓拜受爵位而祝告于神也；“征凶”者，谓逆朝命而有凶也；拜命则平稳无事，故“无咎”也。此占详明，板垣君之宜敬拜受命也，慎勿辞焉。板垣君为阁下旧友，请以余之占辞转为奉告。佐佐木伯曰：子言真切，余亦感铭，必当告之。子须再访后藤象次郎，告以此占。余亦与后藤氏谋，必可使板垣君拜命也。于是余又谒后藤伯，告之如前，且致佐佐木伯之意。后藤伯感谢曰：奇哉！子之《易》占，古今未闻其此也。板垣氏之事余与佐佐木氏谋，必可尽力，请子勿虑。后果闻板垣君拜受爵命。余始心慰。</p>',105)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
